// Flutter/Dart build hook for `package:flutter_wasm`.
//
// The SDK runs this on every build. It compiles the wasmtime C API (a Rust
// `cdylib` inside the `wasmtime/` git submodule) through `src/CMakeLists.txt`
// using package:native_toolchain_cmake, and registers the resulting shared
// library as a native code asset so the SDK bundles it with the application.
//
// The bindings generated by ffigen resolve their symbols from that same asset:
// `ffi-native.asset-id` in `ffigen.yaml` has to match [_assetName] below.

import 'dart:io';

import 'package:code_assets/code_assets.dart'; // input.config.buildCodeAssets
import 'package:hooks/hooks.dart';
import 'package:logging/logging.dart';
import 'package:native_toolchain_cmake/native_toolchain_cmake.dart';

/// Name part of the code asset id `package:flutter_wasm/wasmtime.dart`.
const String _assetName = 'wasmtime.dart';

void main(List<String> args) async {
  await build(args, (input, output) async {
    final logger = Logger('flutter_wasm')
      ..onRecord.listen((record) => stdout.writeln('[flutter_wasm] ${record.message}'));

    // A build that does not produce native code - a web build, where the
    // browser brings its own WebAssembly - has no `code` configuration at all,
    // and nothing to compile.
    if (!input.config.buildCodeAssets) {
      logger.info('no native code for this build, nothing to compile');
      return;
    }

    final installDir = input.outputDirectory.resolve('install/');

    final builder = CMakeBuilder.create(
      name: 'wasmtime',
      sourceDir: input.packageRoot.resolve('src/'),
      defines: <String, String?>{
        'CMAKE_INSTALL_PREFIX': installDir.toFilePath(),
      },
      targets: const <String>['install'],
      logger: logger,
    );
    await builder.run(input: input, output: output, logger: logger);

    final assets = await output.findAndAddCodeAssets(
      input,
      names: <String, String>{r'^(lib)?wasmtime\.(dll|so|dylib)$': _assetName},
      outDir: installDir,
      regExp: true,
      logger: logger,
    );
    if (assets.isEmpty) {
      throw StateError(
        'The wasmtime C API was built but no shared library was found in '
        '${installDir.toFilePath()}.',
      );
    }

    // Anything that changes the wasmtime build must invalidate the cached hook
    // result.
    output.dependencies.add(input.packageRoot.resolve('src/CMakeLists.txt'));
  });
}
